using System.IO.Abstractions;

namespace MyApp.Services;

/// <summary>
/// Decorator wrapper around <see cref="IFileSystem"/> that delegates all calls
/// to an inner instance. Override members to customize behavior (logging, sandboxing, etc.).
/// </summary>
public class FileSystemWrapper : IFileSystem
{
    private readonly IFileSystem _inner;

    public FileSystemWrapper(IFileSystem inner)
    {
        _inner = inner ?? throw new ArgumentNullException(nameof(inner));
    }

    public virtual IDirectory Directory => _inner.Directory;

    public virtual IDirectoryInfoFactory DirectoryInfo => _inner.DirectoryInfo;

    public virtual IDriveInfoFactory DriveInfo => _inner.DriveInfo;

    public virtual IFile File => _inner.File;

    public virtual IFileInfoFactory FileInfo => _inner.FileInfo;

    public virtual IFileStreamFactory FileStream => _inner.FileStream;

    public virtual IFileSystemWatcherFactory FileSystemWatcher => _inner.FileSystemWatcher;

    public virtual IPath Path => _inner.Path;
}

